sbx put extract.js <<'EOF'
#!/usr/bin/env node

const fs = require('fs');

const ELF_CLASS_32 = 1;
const ELF_CLASS_64 = 2;

function u16(buf, off, le) { return le ? buf.readUInt16LE(off) : buf.readUInt16BE(off); }
function u32(buf, off, le) { return le ? buf.readUInt32LE(off) : buf.readUInt32BE(off); }
function u64(buf, off, le) { return Number(le ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off)); }

function parseElfHeader(buf) {
  if (buf.readUInt32BE(0) !== 0x7f454c46) throw new Error('Not a valid ELF file');
  const cls = buf[4];
  const le = buf[5] === 1;
  const is64 = cls === ELF_CLASS_64;
  return {
    cls,
    le,
    shoff: is64 ? u64(buf, 40, le) : u32(buf, 32, le),
    shentsize: u16(buf, is64 ? 58 : 46, le),
    shnum: u16(buf, is64 ? 60 : 48, le),
    shstrndx: u16(buf, is64 ? 62 : 50, le),
  };
}

function parseSections(buf, hdr) {
  const sections = [];
  for (let i = 0; i < hdr.shnum; i++) {
    const off = hdr.shoff + i * hdr.shentsize;
    const is64 = hdr.cls === ELF_CLASS_64;
    sections.push({
      name: u32(buf, off, hdr.le),
      type: u32(buf, off + 4, hdr.le),
      addr: is64 ? u64(buf, off + 16, hdr.le) : u32(buf, off + 12, hdr.le),
      offset: is64 ? u64(buf, off + 24, hdr.le) : u32(buf, off + 16, hdr.le),
      size: is64 ? u64(buf, off + 32, hdr.le) : u32(buf, off + 20, hdr.le),
    });
  }
  return sections;
}

function cString(buf, off) {
  if (off >= buf.length) return '';
  let end = off;
  while (end < buf.length && buf[end] !== 0) end++;
  return buf.slice(off, end).toString();
}

function main(path) {
  const buf = fs.readFileSync(path);
  const hdr = parseElfHeader(buf);
  const sections = parseSections(buf, hdr);
  const shstr = sections[hdr.shstrndx];
  const shstrData = buf.slice(shstr.offset, shstr.offset + shstr.size);

  const wanted = { '.text': null, '.data': null, '.rodata': null };
  for (const s of sections) {
    const name = cString(shstrData, s.name);
    if (name in wanted) wanted[name] = s;
  }

  const memory = {};
  for (const s of [wanted['.text'], wanted['.data'], wanted['.rodata']]) {
    if (!s) continue;
    const data = buf.slice(s.offset, s.offset + s.size);
    for (let i = 0; i + 4 <= data.length; i += 4) {
      memory[s.addr + i] = data.readUInt32LE(i);
    }
  }

  console.log(JSON.stringify(memory));
}

if (require.main === module) {
  if (process.argv.length < 3) {
    console.error('Usage: node extract.js <elf_file>');
    process.exit(1);
  }
  main(process.argv[2]);
}
EOF
